const listUnreadCountsByTopicForMember = `-- name: ListUnreadCountsByTopicForMember :many
SELECT t.id AS topic_id,
       t.conversation_id,
       COUNT(m.id)::bigint AS unread_count
FROM   topic t
JOIN   conversation c ON c.id = t.conversation_id
JOIN   conversation_participant p
       ON p.conversation_id = c.id
JOIN   chat_message m ON m.topic_id = t.id
WHERE  c.workspace_id    = $1
  AND  p.principal_type  = 'member'
  AND  p.principal_id    = $2
  AND  p.left_at IS NULL
  AND  t.archived_at IS NULL
  AND  (p.last_read_at IS NULL OR m.created_at > p.last_read_at)
  AND  NOT (m.sender_type = 'member' AND m.sender_id = $2)
GROUP BY t.id, t.conversation_id
HAVING COUNT(m.id) > 0
`

type ListUnreadCountsByTopicForMemberParams struct {
	WorkspaceID pgtype.UUID `json:"workspace_id"`
	PrincipalID pgtype.UUID `json:"principal_id"`
}

type ListUnreadCountsByTopicForMemberRow struct {
	TopicID        pgtype.UUID `json:"topic_id"`
	ConversationID pgtype.UUID `json:"conversation_id"`
	UnreadCount    int64       `json:"unread_count"`
}

// Read markers: for each non-archived topic the caller participates in
// (across every active membership in this workspace), count how many
// messages were sent by someone else AFTER the caller's last_read_at.
// Drives the FAB aggregate badge AND the per-topic dot in SessionDropdown.
//
// Only returns rows where unread_count > 0 (HAVING) — frontend defaults
// missing topics to 0 so the cardinality stays tiny.
//
// Index notes: WHERE filter hits idx_message_topic_created on
// (topic_id, created_at) and idx_participant_active_lookup on
// (principal_type, principal_id) WHERE left_at IS NULL — both already
// created by the collaboration index migrations.
func (q *Queries) ListUnreadCountsByTopicForMember(ctx context.Context, arg ListUnreadCountsByTopicForMemberParams) ([]ListUnreadCountsByTopicForMemberRow, error) {
	rows, err := q.db.Query(ctx, listUnreadCountsByTopicForMember, arg.WorkspaceID, arg.PrincipalID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListUnreadCountsByTopicForMemberRow{}
	for rows.Next() {
		var i ListUnreadCountsByTopicForMemberRow
		if err := rows.Scan(&i.TopicID, &i.ConversationID, &i.UnreadCount); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const lockConversation = `-- name: LockConversation :one
SELECT id, workspace_id, kind, title, dm_signature, created_by, archived_at, created_at, updated_at FROM conversation WHERE id=$1 FOR UPDATE
`

